<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { ArrowRight, ChevronRight, ShieldCheck, Zap, CreditCard, Check, LockKeyhole, Headphones, PackageCheck, Sparkles, ArrowUpRight } from 'lucide-vue-next'
import { useGetgptCopy } from './siteCopy'
import { useAppStore } from '../../stores/app'
import { usePageSeo } from '../../composables/usePageSeo'
import { postAPI } from '../../api'
import { getLocalizedText } from '../../utils/resellerSiteConfig'
import { getImageUrl } from '../../utils/image'
import FaqSection from './components/FaqSection.vue'

const c = useGetgptCopy()
const app = useAppStore()
const posts = ref<any[]>([])
const selectedStep = ref(0)
const brand = computed(() => app.config?.brand?.site_name || 'XIOEN AI')
const advantages = computed(() => [
  { title: c.value.advantage1, desc: c.value.advantage1d, icon: ShieldCheck },
  { title: c.value.advantage2, desc: c.value.advantage2d, icon: CreditCard },
  { title: c.value.advantage3, desc: c.value.advantage3d, icon: LockKeyhole },
  { title: c.value.advantage4, desc: c.value.advantage4d, icon: Zap },
])
const steps = computed(() => [
  { title: c.value.step1, desc: c.value.step1d }, { title: c.value.step2, desc: c.value.step2d }, { title: c.value.step3, desc: c.value.step3d },
])
const service = computed(() => [
  { title: c.value.service1, desc: c.value.service1d, icon: Sparkles },
  { title: c.value.service2, desc: c.value.service2d, icon: PackageCheck },
  { title: c.value.service3, desc: c.value.service3d, icon: Headphones },
])
usePageSeo({ title: () => `${c.value.heroTitle} ${c.value.heroTitle2}`, description: () => c.value.heroDesc })
onMounted(async () => {
  try { const response = await postAPI.list({ type: 'blog', page_size: 3 }); posts.value = response.data.data || [] } catch { /* Guides remain available without published blog posts. */ }
})
</script>

